from pathlib import Path
p=Path(__file__).parent/'frontend/src/main.jsx'
s=p.read_text(encoding='utf-8')
s=s.replace("setRid(Number(e.target.value));setTank('todos')", "setRid(Number(e.target.value));setTank('todos');setFollowing(true);setHour(0)")
s=s.replace('max="84" value={hour} onChange={e=>setHour(Number(e.target.value))}', 'max={isLive?(liveState?.hora??0):84} value={hour} onChange={e=>chooseHour(Number(e.target.value))}')
s=s.replace('onSelect={setHour}', 'onSelect={chooseHour}')
anchor=" {loading&&view!=='simulaciones'"
block=''' {isLive&&liveState&&view!=='simulaciones'&&<section className="live-bar" aria-label="Control de simulación en vivo"><div className="live-caption"><Radio size={18}/><div><b>{liveState.estado==='activa'?'Simulación en vivo':liveState.estado==='terminada'?'Simulación finalizada':liveState.estado==='error'?'Error de simulación':'Simulación pausada'}</b><span>{liveState.segundos} segundo{liveState.segundos===1?'':'s'} real{liveState.segundos===1?'':'es'} = 1 hora simulada · Hora calculada: {liveState.hora} / 96</span></div></div><div className="live-actions"><select aria-label="Velocidad de simulación" value={liveState.segundos} disabled={controlling||liveState.estado==='terminada'} onChange={e=>liveControl('velocidad',Number(e.target.value))}><option value="0.5">1 hora / 0,5 s</option><option value="1">1 hora / 1 s</option><option value="2">1 hora / 2 s</option><option value="5">1 hora / 5 s</option></select><button className="button" disabled={controlling||['terminada','error'].includes(liveState.estado)} onClick={()=>liveControl(liveState.estado==='activa'?'pausar':'reanudar')}>{liveState.estado==='activa'?<Pause size={15}/>:<Play size={15}/>} {liveState.estado==='activa'?'Pausar':'Reanudar'}</button>{!following&&<button className="button primary" onClick={()=>setFollowing(true)}>Volver al presente</button>}</div><div className="live-note">{following?'La vista sigue el reloj del servidor.':'Revisando la hora '+hour+'. El servidor continúa con su reloj.'} {liveState.nota} {liveState.error} {hour+h>96?'Esta predicción supera el fin del seguimiento; su desenlace quedará sin evaluar.':''}</div></section>}
'''
assert anchor in s
s=s.replace(anchor,block+anchor)
s=s.replace('<form onSubmit={simulate} className="sim-form"><label>Ambiente', '<form onSubmit={simulate} className="sim-form"><label>Modo de ejecución<select value={mode} onChange={e=>setMode(e.target.value)}><option value="vivo">En vivo · una hora por segundo</option><option value="completa">Calcular corrida completa</option></select></label><label>Ambiente')
s=s.replace('<select value={reps} onChange={e=>setReps(Number(e.target.value))}>','<select value={mode===\'vivo\'?1:reps} disabled={mode===\'vivo\'} onChange={e=>setReps(Number(e.target.value))}>')
s=s.replace("{r.origen==='test_v3'?'Prueba reservada v3':'Prueba nueva'}", "{r.origen==='vivo'?'Motor en vivo':r.origen==='test_v3'?'Prueba reservada v3':'Prueba nueva'}")
s=s.replace("{r.estado==='lista'?'Terminada':r.estado==='pendiente'?'En espera':r.estado==='ejecutando'?'Calculando…':'Error'}", "{r.vivo?`${r.vivo.estado} · hora ${r.vivo.hora}`:r.estado==='lista'?'Terminada':r.estado==='pendiente'?'En espera':r.estado==='ejecutando'?'Calculando…':'Error'}")
s=s.replace("setRid(r.id);setHour(48);setTank('todos');setView('resumen')", "setRid(r.id);setHour(r.vivo?.hora??48);setFollowing(true);setTank('todos');setView('resumen')")
s=s.replace('<td>{pct(r.recall)}</td><td>{pct(r.precision)}</td><td>{num(r.fp)}</td>', '<td>{r.pendiente?\'Pendiente\':pct(r.recall)}</td><td>{r.pendiente?\'Pendiente\':pct(r.precision)}</td><td>{r.pendiente?\'Pendiente\':num(r.fp)}</td>')
s=s.replace("<b>{pct(t.riesgo_medio)}</b>","<b>{t.peces?pct(t.riesgo_medio):'Sin peces'}</b>")
s=s.replace("tone={t.alertas?'amber':'green'}>{t.alertas?`${t.alertas} peces con alerta`:'Sin alertas en este corte'}", "tone={!t.peces?'':t.alertas?'amber':'green'}>{!t.peces?'Sin peces vivos':t.alertas?`${t.alertas} peces con alerta`:'Sin alertas en este corte'}")
p.write_text(s,encoding='utf-8')
